// Command legagent 啟動立法委員服務 Agent 的 gRPC 伺服器。
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose 組裝 config → logger → embedding → 向量庫 → service → gRPC，不含業務邏輯
package main

import (
	"net"
	"os"
	"os/signal"
	"syscall"

	"google.golang.org/grpc"
	"google.golang.org/grpc/reflection"

	"github.com/maoxiaoyue/hypgo/pkg/logger"
	"github.com/maoxiaoyue/hypgo/pkg/manifest"
	"github.com/maoxiaoyue/hypgo/pkg/router"

	"legagent/app/config"
	pb "legagent/app/proto/legagentpb"
	"legagent/app/rpc"
	"legagent/app/services"
	"legagent/internal/embed"
	"legagent/internal/vectorstore"
)

const configPath = "app/config/config.yaml"

func main() {
	cfg, err := config.Load(configPath)
	if err != nil {
		boot, _ := logger.New("error", "stderr", nil, false)
		boot.Error("load config failed", "path", configPath, "err", err)
		os.Exit(1)
	}
	log, _ := logger.New(cfg.Logger.Level, cfg.Logger.Output, nil, cfg.Logger.Colors)

	embedder, desc, err := embed.New(embed.Config{
		Provider: cfg.Embedding.Provider, BaseURL: cfg.Embedding.BaseURL,
		APIKey: cfg.Embedding.APIKey, Model: cfg.Embedding.Model,
	})
	if err != nil {
		log.Error("build embedder failed", "err", err)
		os.Exit(1)
	}
	store, err := vectorstore.NewChromem(vectorstore.Options{
		Path: cfg.Vector.Path, Collection: cfg.Vector.Collection, Compress: cfg.Vector.Compress,
		Metadata: map[string]string{"embedding": desc},
	}, embedder)
	if err != nil {
		log.Error("open vector store failed", "path", cfg.Vector.Path, "err", err)
		os.Exit(1)
	}
	log.Info("vector store ready", "path", cfg.Vector.Path, "collection", cfg.Vector.Collection, "documents", store.Count(), "embedder", desc)
	if store.Count() == 0 {
		log.Warn("rule index is empty; run: go run ./tools/ingest -config app/config/config.yaml")
	}
	rules := services.NewRulesService(store, cfg.Rules.DataDir, log, cfg.Embedding.Concurrency)

	lis, err := net.Listen("tcp", cfg.GRPC.Addr)
	if err != nil {
		log.Error("listen failed", "addr", cfg.GRPC.Addr, "err", err)
		os.Exit(1)
	}

	s := grpc.NewServer(
	// Interceptor（中間件）可在此加入：
	// grpc.ChainUnaryInterceptor(interceptor.Recovery(log), interceptor.Logger(log)),
	)
	pb.RegisterLegagentServiceServer(s, rpc.NewLegagentServer(rules, log))

	// 註冊 Schema（Protocol "grpc"；供 hyp context / contract.TestAll 理解服務介面）
	rpc.RegisterSchemas()

	// 同步 manifest 到 .hyp/context.yaml（gRPC 不走 server.Start 的 AutoSync，故啟動時主動寫一次）
	manifest.NewAutoSync(manifest.AutoSyncConfig{Enabled: true}, router.New(), nil, nil).SyncSafe()

	// 啟用 gRPC reflection（方便 grpcurl 偵錯）
	reflection.Register(s)

	log.Info("gRPC server listening", "addr", cfg.GRPC.Addr)
	go func() {
		if err := s.Serve(lis); err != nil {
			log.Error("serve failed", "err", err)
			os.Exit(1)
		}
	}()

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	log.Info("shutting down gRPC server")
	s.GracefulStop()
	log.Info("server stopped")
}
